SELECT DISTINCT cn.name FROM dtb_product_class pc INNER JOIN dtb_class_category cc1 ON cc1.id = pc.class_category_id1 INNER JOIN dtb_class_name cn ON cn.id = cc1.class_name_id WHERE pc.product_id = :productId UNION SELECT DISTINCT cn.name FROM dtb_product_class pc INNER JOIN dtb_class_category cc2 ON cc2.id = pc.class_category_id2 INNER JOIN dtb_class_name cn ON cn.id = cc2.class_name_id WHERE pc.product_id = :productId
